export default function plan({ values, sheet }) {
  if (!Array.isArray(values) || !values.length) return { rows: [] };
  const h = values[0],
    names = ["Pricing URL", "Pricing", "Time"],
    idx = names.map((x) => h.indexOf(x));
  if (idx.some((n, i) => n < 0 || h.lastIndexOf(names[i]) !== n))
    throw Error("Sheet requires unique Pricing URL, Pricing and Time headers");
  function col(n) {
    let s = "";
    for (n++; n; n = Math.floor((n - 1) / 26)) s = String.fromCharCode(65 + ((n - 1) % 26)) + s;
    return s;
  }
  const tab = "'" + sheet.replaceAll("'", "''") + "'";
  return {
    rows: values
      .slice(1)
      .map((r, i) => ({
        url: String(r[idx[0]] ?? "").trim(),
        previous: String(r[idx[1]] ?? ""),
        priceRange: `${tab}!${col(idx[1])}${i + 2}`,
        timeRange: `${tab}!${col(idx[2])}${i + 2}`,
      }))
      .filter((x) => x.url),
  };
}

