export default function next({ rows, previous }) {
  const index = (previous?.index ?? -1) + 1;
  if (index >= rows.length)
    return { state: { index }, more: false, person: "", range: "{}", url: "https://example.com/" };
  const r = rows[index];
  let u;
  try {
    u = new URL(r.url);
  } catch {
    throw Error("Invalid pricing URL");
  }
  if (!["http:", "https:"].includes(u.protocol)) throw Error("Expected HTTP pricing URL");
  return {
    state: { index },
    more: true,
    person: r.previous,
    range: JSON.stringify({ price: r.priceRange, time: r.timeRange, url: r.url }),
    url: r.url,
  };
}

