export default function query({ body, terminateUrl, person }) {
  const id = body?.data?.windowId;
  if (typeof id !== "string" || !/^[-a-z0-9]+$/i.test(id) || body.errors?.length)
    throw Error("Invalid Airtop window");
  const schema = {
    type: "object",
    properties: {
      pricing_summary: { type: "string" },
      differences_summary: { type: "string" },
      status: { type: "string" },
    },
    required: ["pricing_summary", "differences_summary", "status"],
    additionalProperties: false,
  };
  return {
    url: terminateUrl + "/windows/" + encodeURIComponent(id) + "/page-query",
    query: {
      prompt: `This is a pricing page. Summarize every plan with price and top 3 features. Compare prices to the previous summary below. Return pricing_summary, differences_summary and status: [DIFF] for significant price differences, [SIMILAR] for similar prices, [NEW] when no previous summary. Do not guess. Previous summary: ${person}`,
      configuration: { outputSchema: JSON.stringify(schema) },
    },
  };
}

