export default function result({ body, range }) {
  if (body?.errors?.length || typeof body?.data?.modelResponse !== "string")
    throw Error("Invalid Airtop response");
  let x, r;
  try {
    x = JSON.parse(body.data.modelResponse);
    r = JSON.parse(range);
  } catch {
    throw Error("Invalid pricing response");
  }
  if (
    typeof x.pricing_summary !== "string" ||
    typeof x.differences_summary !== "string" ||
    typeof x.status !== "string" ||
    !r.price ||
    !r.time ||
    !r.url
  )
    throw Error("Incomplete pricing response");
  return {
    changed: !x.status.includes("SIMILAR"),
    data: [
      { range: r.price, values: [[x.pricing_summary]] },
      { range: r.time, values: [[new Date().toISOString()]] },
    ],
    message: r.url + " - " + x.differences_summary,
  };
}
